import django.db.models.deletion
import os
from decimal import Decimal

from django.db import migrations, models


def seed_starter_plan(apps, schema_editor):
    """Creates the Starter plan and puts every existing clinic on it.
    Clinics that existed before billing keep working: they are marked active (no trial, no Stripe
    subscription) until they add a card or the Super Admin changes them."""
    Plan = apps.get_model('tenants', 'Plan')
    Clinic = apps.get_model('tenants', 'Clinic')
    plan = Plan.objects.order_by('id').first()
    if plan is None:
        plan = Plan.objects.create(
            name='Starter',
            price=Decimal(os.environ.get('STARTER_PLAN_PRICE', '0') or '0'),
            currency=os.environ.get('STARTER_PLAN_CURRENCY', 'eur') or 'eur',
            stripe_price_id=os.environ.get('STRIPE_STARTER_PRICE_ID', ''),
        )
    Clinic.objects.filter(plan__isnull=True).update(plan=plan)
    Clinic.objects.update(subscription_status='active')


